            "**[Confirmado]:** Videos de navegación marítima confirmaron la presencia de una extensa red de islas unidas por puentes, emulando los Cayos de Florida.",
            "**3. Port Gellhorn y Grassrivers**",
            "**[Confirmado]:** Presencia de áreas de autopistas secundarias, zonas de pantanos con vegetación densa y poblados interiores como Port Gellhorn y Ambrosia."
